messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_order",
   "legacy_table": "db_pagos..pg_orden",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ord_numero"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ord_empresa"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ord_estado"
    },
    {
     "name": "paymentDate",
     "type": "timestamp(local)",
     "column": "payment_date",
     "legacy": "ord_fecha_pago"
    },
    {
     "name": "commission",
     "type": "decimal(19,4,signed)",
     "column": "commission",
     "legacy": "ord_comision"
    }
   ]
  },
  {
   "name": "CompanyTariff",
   "table": "company_tariff",
   "legacy_table": "db_admin..ad_tarifa_empresa",
   "key": [
    "companyId",
    "serviceCode"
   ],
   "fields": [
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "tar_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "tar_servicio"
    },
    {
     "name": "tariffValue",
     "type": "decimal(19,4,signed)",
     "column": "tariff_value",
     "legacy": "tar_valor"
    },
    {
     "name": "chargedSeparately",
     "type": "text(fixed,1,iso8859-1)",
     "column": "charged_separately",
     "legacy": "tar_separada"
    }
   ]
  },
  {
   "name": "ServiceCatalog",
   "table": "service_catalog",
   "legacy_table": "db_admin..ad_servicio",
   "key": [
    "serviceCode"
   ],
   "fields": [
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "srv_codigo"
    },
    {
     "name": "defaultTariff",
     "type": "decimal(19,4,signed)",
     "column": "default_tariff",
     "legacy": "srv_tarifa"
    }
   ]
  },
  {
   "name": "Account",
   "table": "account",
   "legacy_table": "db_cuentas..ct_cuenta",
   "key": [
    "accountNumber",
    "accountType"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": "account_number",
     "legacy": "cta_numero"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "cta_tipo"
    },
    {
     "name": "balance",
     "type": "decimal(19,4,signed)",
     "column": "balance",
     "legacy": "cta_saldo"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "PaymentOrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndCompany",
     "description": "Reads the order by number and company. Empty when it does not exist.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets status 'A', payment date and commission on the order. Returns the number of rows updated.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "paymentDate",
       "type": "timestamp(local)",
       "column": null,
       "legacy": "@i_fecha_proceso"
      },
      {
       "name": "commission",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@w_comision"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "CompanyTariffRepository",
   "entity": "CompanyTariff",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCompanyAndService",
     "description": "Reads the company-specific tariff of a service. Empty when the company has none.",
     "inputs": [
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "CompanyTariff",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "ServiceCatalogRepository",
   "entity": "ServiceCatalog",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCode",
     "description": "Reads the service with its default tariff. Empty when it does not exist.",
     "inputs": [
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "ServiceCatalog",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndType",
     "description": "Reads the account with its balance. Empty when it does not exist.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo_cuenta"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": null,
   "legacy_program": "db_cuentas..sp_debito",
   "methods": [
    {
     "name": "debitAccount",
     "description": "Debits the account for the order total with the given reference and returns the movement sequence. A non-zero return code from the legacy program is raised as an exception.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "amount",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "reference",
       "type": "text(var,20,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "int",
     "legacy_output": "@o_secuencial"
    },
    {
     "name": "debitCommission",
     "description": "Debits the separately charged commission. The movement sequence is not used. A non-zero return code from the legacy program is raised as an exception.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "amount",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "reference",
       "type": "text(var,20,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Pays a pending order: validates account type and order, resolves the tariff and commission, checks funds, debits the account (and the commission when charged separately) and marks the order as paid, all in one transaction.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011"
   ],
   "inputs": [
    {
     "name": "orden",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "empresa",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "servicio",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "tipoCuenta",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "cuenta",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "valor",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "canal",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "fechaProceso",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movimiento",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "mensaje",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "50001",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "50002",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "50003",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "50004",
     "message": "FONDOS INSUFICIENTES"
    },
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_DEBIT_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "PaymentOrderRepository",
    "CompanyTariffRepository",
    "ServiceCatalogRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/payments",
   "legacy_program": "dbo.sp_pago_orden",
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Single use case and single transaction",
   "context": "The legacy validates without a transaction, then opens 'begin tran' before the first debit and commits after updating the order.",
   "decision": "PayOrder is one use case. Validations and calculations run first without writes. The debit(s) and the order update run in one @Transactional block. Any business error after the first debit raises an exception that rolls back the transaction.",
   "consequences": "Reproduces the rollback tran of the legacy. DebitGateway must take part in the same transaction (same database or a shared transaction manager). If the accounts system is remote, a compensating reversal is needed and is outside this design."
  },
  {
   "title": "Rule evaluation order preserved",
   "context": "The legacy stops at the first failing check (goto ERROR): account type, order exists, order pending, funds, debit, commission, update.",
   "decision": "The use case evaluates the checks in the same order and stops at the first failure, so the error code and message match.",
   "consequences": "Golden master responses match for every rejection path."
  },
  {
   "title": "Tariff resolution and null handling",
   "context": "The tariff comes from the company row, else from the service default with separada 'N'. A null tariff counts as 0. If neither row exists, the legacy variables stay null.",
   "decision": "Company tariff first (tariffValue and chargedSeparately). Otherwise the service default and 'N'. A null or missing tariff is 0. A missing separada flag is treated as not separate, which gives the same total as the legacy comparison (separada = 'S' is false).",
   "consequences": "An unknown service does not cause an error, as in the legacy, and pays no commission."
  },
  {
   "title": "Commission rounding",
   "context": "The legacy computes round(tariff / 2, 2) on Sybase money for the WEB channel. NOMINA is applied last and forces 0.",
   "decision": "Use BigDecimal with scale 4 and RoundingMode.HALF_UP for the division by 2 rounded to 2 decimals (1.25 gives 0.63). The NOMINA exemption overrides the channel rule. The result is stored with decimal(19,4).",
   "consequences": "Amounts match the legacy for positive tariffs. Negative tariffs are not expected."
  },
  {
   "title": "Funds check with a missing account",
   "context": "If the account does not exist, @w_saldo stays null. The legacy comparison is then unknown, so it does not raise 50004 and goes on to sp_debito.",
   "decision": "A missing account is treated as a null balance: the funds check is skipped and the debit is attempted. The outcome is whatever the debit gateway returns, normally 50005 ERROR EN DEBITO.",
   "consequences": "Same behaviour as the legacy. It is not changed to a new error code without business approval."
  },
  {
   "title": "Default channel",
   "context": "@i_canal defaults to 'WEB' in the legacy.",
   "decision": "When the request has no canal, the use case uses 'WEB'.",
   "consequences": "Callers that omit the channel keep receiving the half-tariff commission."
  },
  {
   "title": "Debit gateway failures as exceptions",
   "context": "sp_debito returns a code. Non-zero means failure, and the legacy also checks @@error after the first debit.",
   "decision": "DebitGateway raises an exception on a non-zero code or a technical error. The use case maps it to DEBIT_FAILED (first debit) or COMMISSION_DEBIT_FAILED (separate commission) and rolls back.",
   "consequences": "No return-code plumbing or @@error checks in the target. The debit reference texts 'PAGO ORDEN' and 'COMISION PAGO' are kept."
  },
  {
   "title": "Error logging and messages",
   "context": "The legacy calls cobis..sp_cerror to log and raise the error, and sets 'PAGO REALIZADO' on success.",
   "decision": "sp_cerror is not translated. Business exceptions with stable codes are mapped to HTTP errors by the framework. The message is still returned in 'mensaje', and 'PAGO REALIZADO' is returned on success.",
   "consequences": "Clients keep the same messages. Logging is done by the framework."
  }
 ],
 "masks": [
  {
   "path": "outputs:@o_movimiento",
   "when": "rejected",
   "reason": "When the commission debit or the order update fails after the first debit succeeded, the legacy leaves the movement sequence in the output parameter even though the transaction is rolled back. The target returns no movement on any rejection, because the movement no longer exists after the rollback."
  }
 ],
 "infrastructure": [
  "cobis..sp_cerror"
 ]
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Permitted account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "An order payment is only accepted for account types 'CTE', 'AHO' or 'VIR'. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is permitted\n  Given @i_tipo_cuenta is 'AHO'\n  When the payment order is validated\n  Then no error is raised for the account type",
   "Scenario: Account type is not permitted\n  Given @i_tipo_cuenta is 'PRE'\n  When the payment order is validated\n  Then @w_error is 50001 and @o_mensaje is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Only pending orders can be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order can only be processed if its status is 'P' (pending). If the order is in any other status, it is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "ord_estado of the order (ord_numero = @i_orden, ord_empresa = @i_empresa) in db_pagos..pg_orden <> 'P'",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   },
   {
    "name": "@i_orden",
    "type": "text(fixed,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Pending order passes the check\n  Given order 'ORD0000001' of company 'E01' has status 'P'\n  When the payment of the order is requested\n  Then no error 50003 is raised and processing may continue",
   "Scenario: Non-pending order is rejected\n  Given order 'ORD0000001' of company 'E01' has status 'C'\n  When the payment of the order is requested\n  Then error 50003 is set\n  And the message is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment requires an existing order",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment cannot be processed for an order that does not exist. When the order lookup returns no rows, the procedure reports error 50002 with the message 'ORDEN NO EXISTE'.",
  "condition": "The preceding query (not shown in this slice) affected or returned zero rows (@@rowcount = 0).",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'.",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the order lookup for the payment returns no rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the order lookup returns one row\n  When the payment procedure evaluates the result\n  Then error 50002 is not raised by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Company-specific service tariff with default fallback",
  "category": "calculation",
  "priority": "P0",
  "statement": "The service tariff is taken from the company-specific tariff for the service, together with its 'charged separately' flag. If the company has no specific tariff, the service's default tariff applies and the commission is never charged separately ('N'). A missing tariff is treated as 0.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise (@@rowcount = 0) use ad_servicio where srv_codigo = @i_servicio; if the resulting tariff is null.",
  "action": "With a company row: tariff = tar_valor and separada = tar_separada. Without one: tariff = srv_tarifa and separada = 'N'. If the tariff is still null, tariff = 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company-specific tariff\n Given company 15 has a tariff of 2.00 for service 'LUZ' with separada 'S'\n When the payment is processed\n Then the tariff is 2.00 and separada is 'S'",
   "Scenario: Fallback to the service default\n Given company 15 has no tariff row for service 'AGUA' and the service default tariff is 1.50\n When the payment is processed\n Then the tariff is 1.50 and separada is 'N'",
   "Scenario: Missing tariff\n Given the tariff found is null\n When the payment is processed\n Then the tariff is 0"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 62,
    "line_end": 66
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 68,
    "line_end": 68
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 70,
    "line_end": 72
   },
