```java
package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.model.ServiceCatalog;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.CompanyTariffRepository;
import com.bank.payments.domain.port.DebitGateway;
import com.bank.payments.domain.port.PaymentOrderRepository;
import com.bank.payments.domain.port.ServiceCatalogRepository;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Use case PayOrder (legacy dbo.sp_pago_orden). */
public class PayOrderService {

    private static final BigDecimal OVERDRAFT_MARGIN = new BigDecimal("100.00");

    private final PaymentOrderRepository orders;
    private final CompanyTariffRepository companyTariffs;
    private final ServiceCatalogRepository serviceCatalog;
    private final AccountRepository accounts;
    private final DebitGateway debitGateway;

    public PayOrderService(PaymentOrderRepository orders,
                           CompanyTariffRepository companyTariffs,
                           ServiceCatalogRepository serviceCatalog,
                           AccountRepository accounts,
                           DebitGateway debitGateway) {
        this.orders = orders;
        this.companyTariffs = companyTariffs;
        this.serviceCatalog = serviceCatalog;
        this.accounts = accounts;
        this.debitGateway = debitGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        String tipoCuenta = request.tipoCuenta();

        // RULE-001
        if (!("CTE".equals(tipoCuenta) || "AHO".equals(tipoCuenta) || "VIR".equals(tipoCuenta))) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003
        Optional<PaymentOrder> orderOpt = orders.findByNumberAndCompany(request.orden(), request.empresa());
        if (orderOpt.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        // RULE-002
        if (!"P".equals(orderOpt.get().status())) {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004 / RULE-005
        BigDecimal tariff;
        String separada;
        Optional<CompanyTariff> companyTariff =
                companyTariffs.findByCompanyAndService(request.empresa(), request.servicio());
        if (companyTariff.isPresent()) {
            tariff = companyTariff.get().tariffValue();
            separada = companyTariff.get().chargedSeparately();
        } else {
            Optional<ServiceCatalog> service = serviceCatalog.findByCode(request.servicio());
            tariff = service.map(ServiceCatalog::defaultTariff).orElse(null);
            separada = "N";
        }
        if (tariff == null) {
            tariff = BigDecimal.ZERO;
        }

        // RULE-006
        String canal = request.canal() == null ? "WEB" : request.canal();
        BigDecimal commission;
        if ("WEB".equals(canal)) {
            commission = tariff.divide(new BigDecimal("2"), 4, RoundingMode.HALF_UP)
                    .setScale(2, RoundingMode.HALF_UP);
        } else {
            commission = tariff;
        }
        if ("NOMINA".equals(request.servicio())) {
            commission = BigDecimal.ZERO;
        }
        commission = commission.setScale(4, RoundingMode.HALF_UP);

        // RULE-007
        boolean separate = "S".equals(separada);
        BigDecimal total = separate ? request.valor() : request.valor().add(commission);

        // RULE-008 (a missing account means a null balance: the check is skipped)
        BigDecimal balance = accounts.findByNumberAndType(request.cuenta(), tipoCuenta)
                .map(Account::balance)
                .orElse(null);
        if (balance != null) {
            boolean insufficient;
            if ("VIR".equals(tipoCuenta)) {
                insufficient = balance.compareTo(total) < 0;
            } else {
                insufficient = balance.add(OVERDRAFT_MARGIN).compareTo(total) < 0;
            }
            if (insufficient) {
                throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
            }
        }

        // RULE-009
        int movement;
        try {
            movement = debitGateway.debitAccount(request.cuenta(), tipoCuenta, total, "PAGO ORDEN");
        } catch (RuntimeException e) {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        // RULE-010
        if (separate && commission.signum() > 0) {
            try {
                debitGateway.debitCommission(request.cuenta(), tipoCuenta, commission, "COMISION PAGO");
            } catch (RuntimeException e) {
                throw new BusinessError("COMMISSION_DEBIT_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011
        int updated = orders.markPaid(request.orden(), request.empresa(), request.fechaProceso(), commission);
        if (updated <= 0) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        return new PayOrderResponse(movement, "PAGO REALIZADO");
    }
}
